              </g>
              <g fill="#cf653e"><circle cx="96" cy="64" r="4"/><circle cx="284" cy="64" r="4"/><circle cx="96" cy="222" r="4"/><circle cx="284" cy="222" r="4"/></g>
              <circle cx="190" cy="143" r="48" fill="#d36640"/>
              <g fill="#fff7e7" text-anchor="middle"><text x="190" y="145" font-size="22" font-weight="600" lang="ja">手応え</text><text x="190" y="165" font-size="9" letter-spacing="1">TEGOTAE</text></g>
              <g fill="#f7f3e9" font-size="12" text-anchor="middle">
                <text x="75" y="39">Visuals</text><text x="298" y="30">Motion, sound</text><text x="298" y="46">&amp; music</text>
                <text x="75" y="248">Workflow</text><text x="298" y="248">Decisions &amp; logic</text>
